int map_user_io(struct request_queue *q, struct request *rq, struct rq_map_data *map_data,
                const struct iov_iter *iter, gfp_t gfp_mask) {
    int ret = 0;
    size_t iov_offset = 0;
    struct bio *bio = NULL;

    while (iov_iter_count(iter)) {
        struct bio *new_bio;
        struct iov_iter i = *iter;

        i.iov_base = (void *)((uintptr_t)i.iov_base + iov_offset);
        i.count = min(i.count, (size_t)(PAGE_SIZE - (uintptr_t)i.iov_base % PAGE_SIZE));

        new_bio = bio_kunmap_or_alloc(&i, gfp_mask);
        if (!new_bio) {
            ret = -EINVAL;
            break;
        }

        if (!bio) {
            bio = new_bio;
        } else {
            bio_chain(rq->bio, new_bio);
        }

        iov_offset += i.count;
        iter->count -= i.count;
        iter->iov++;
    }

    if (ret) {
        if (bio)
            bio_unmap_user(bio);
        return ret;
    }

    rq->cmd_flags |= REQ_USER_MAPPED;
    rq->bio = bio;

    return 0;
}

int blk_rq_map_user(struct request_queue *q, struct request *rq, struct rq_map_data *map_data,
                    const struct iov_iter *iter, gfp_t gfp_mask) {
    struct bio *bio = NULL;
    size_t len;
    int ret;

    if (!iov_iter_count(iter))
        return -EINVAL;

    len = iov_iter_count(iter);

    bio = bio_kmalloc(gfp_mask, 1);
    if (!bio)
        return -ENOMEM;

    ret = __blk_rq_map_iter(q, iter, bio, gfp_mask);
    if (ret)
        goto unmap;

    bio->bi_private = map_data;
    rq->bio = bio;
    rq->ioprio = map_data->ioprio;
    rq->cmd_flags |= REQ_USER_MAPPED;

    return 0;

unmap:
    __blk_unmap_bios(bio);
    bio_put(bio);
    return ret;
}

int map_user_io(struct request_queue *q, struct request *rq, struct rq_map_data *map_data,
                const struct iov_iter *iter, gfp_t gfp_mask) {
    struct bio *bio = NULL;
    int ret = 0;
    size_t iov_offset = 0;

    while (iov_iter_count(iter)) {
        struct bio *new_bio;
        struct iovec *iov;
        ssize_t len;

        iov = iov_iter_iovec(iter);
        len = iov_iter_single_seg_length(iter);

        new_bio = bio_alloc(gfp_mask, 0);
        if (!new_bio) {
            ret = -EINVAL;
            goto unmap_error;
        }

        if (bio) {
            bio->bi_next = new_bio;
        } else {
            rq->bio = new_bio;
        }

        bio->bi_iter.bi_sector = 0;
        bio->bi_bdev = NULL;
        bio_add_page(new_bio, virt_to_page(iov->iov_base + iov_offset), len, iov_offset);

        iov_offset += len;
        iov_iter_advance(iter, len);
        bio = new_bio;
    }

    rq->cmd_flags |= REQ_USER_MAPPED;
    return 0;

unmap_error:
    while (rq->bio) {
        struct bio *next = rq->bio->bi_next;
        bio_put(rq->bio);
        rq->bio = next;
    }
    return ret;
}

int map_user_io(struct request_queue *q, struct request *rq, struct rq_map_data *map_data,
                const struct iov_iter *iter, gfp_t gfp_mask) {
    struct bio *bio = NULL;
    int ret = 0;

    if (!iov_iter_count(iter))
        return 0;

    if (!map_data || !map_data->pages)
        return -EINVAL;

    while (iov_iter_count(iter)) {
        size_t bytes;
        unsigned long idx;

        bytes = min(iov_iter_count(iter), (size_t)QUEUE_MAX_BYTES(q));
        idx = map_data->offset >> PAGE_SHIFT;

        bio = bio_alloc(GFP_NOIO, 1);
        if (!bio)
            return -ENOMEM;

        ret = iov_iter_get_pages(iter, &map_data->pages[idx], bytes, 1, &map_data->offset);
        if (ret < 0) {
            if (bio)
                bio_put(bio);
            return -EINVAL;
        }

        bio_add_page(bio, map_data->pages[idx], ret, 0);
        submit_bio(bio);
    }

    rq->cmd_flags |= REQ_USER_MAPPED;
    return 0;
}

int map_user_io(struct request_queue *q, struct request *rq, struct rq_map_data *map_data,
                const struct iov_iter *iter, gfp_t gfp_mask) {
    struct bio *bio = NULL;
    struct bio *prev_bio = NULL;
    size_t offset = 0;
    ssize_t bytes;
    int ret = 0;

    while ((bytes = iov_iter_next(iter, &offset))) {
        bio = bio_alloc(gfp_mask, 1);
        if (!bio) {
            ret = -EINVAL;
            break;
        }

        bio->bi_bdev = map_data->bdev;
        bio->bi_sector = map_data->start_sector + (offset >> 9);
        bio->bi_size = bytes;

        if (prev_bio) {
            prev_bio->bi_next = bio;
        } else {
            rq->bio = bio;
        }

        prev_bio = bio;
        bio = NULL;
    }

    if (ret < 0) {
        bio = rq->bio;
        while (bio) {
            struct bio *next = bio->bi_next;
            bio_put(bio);
            bio = next;
        }
        rq->bio = NULL;
    } else {
        rq->cmd_flags |= REQ_USER_MAPPED;
    }

    return ret;
}
